const F     = DATA.floor;              // 150：分母口径
const YEARS = DATA.years;              // 按年份升序
const BY    = new Map(YEARS.map(y => [y.year, y]));
const NEW_ERA = 2020;                  // 与上一年之间有十年空档

/* cum[i] = 得分 >= (base+i) 的人数。base 是该年逐分公布到的最低分。 */
const cumAt = (y, s) => y.cum[s - y.base];
const topCum = y => y.cum[y.cum.length - 1];

/* 分数 -> 位次。超出逐分公布范围时只能给出边界。 */
function rankOf(y, s){
  if (s > y.top)   return { rank:topCum(y), bound:"above" };  // 落在「XXX 分以上」一档
  if (s < y.base)  return { rank:y.cum[0],  bound:"under" };  // 低于该年公布的最低分
  return { rank:cumAt(y, s), bound:"" };
}

/* 位次 -> 分数：满足「该分及以上人数 >= R」的最高分。 */
function scoreAt(y, R){
  const cum = y.cum, n = cum.length;
  if (cum[n-1] >= R) return { score:y.top,  bound:"above" };
  if (R > cum[0])    return { score:y.base, bound:"under" };
  let lo = 0, hi = n - 1;
  while (lo < hi){ const mid = (lo + hi + 1) >> 1; if (cum[mid] >= R) lo = mid; else hi = mid - 1; }
  return { score:y.base + lo, bound:"" };
}

/* 源年某分 -> 目标年等位分 */
function convert(src, score, tgt){
  const p = rankOf(src, score).rank / src.total;
  const R = Math.max(1, Math.round(p * tgt.total));
  const r = scoreAt(tgt, R);
  // 等位分只能取整，实际落点会比目标位次略靠后，这里一并报出实际值
  const real = r.bound === "under" ? tgt.cum[0] : cumAt(tgt, r.score);
  return { pct:p, rank:R, score:r.score, bound:r.bound, real:real };
}

/* ------------------------------------------------------------- 格式化 */
const $      = id => document.getElementById(id);
const fmt    = n => Math.round(n).toLocaleString("en-US");
const wan    = n => (n/10000).toFixed(1);
const signed = n => (n > 0 ? "+" : n < 0 ? "−" : "±") + Math.abs(n);
const prefix = b => b === "above" ? "≥" : b === "under" ? "<" : "";
function pctText(p){
  const v = p * 100;
  if (v < 0.01) return v.toFixed(4) + "%";
  if (v < 1)    return v.toFixed(3) + "%";
  if (v < 10)   return v.toFixed(2) + "%";
  return v.toFixed(1) + "%";
}
function tags(y, score){
  let out = '<span class="tag">' + y.track + "</span>";
  if (y.estimated) out += '<span class="tag est" title="' + y.estBasis + '">分母估计</span>';
  if (isCoarse(y, score))
    out += '<span class="tag est" title="该年 ' + y.coarseAbove +
           ' 分以上只有段端点，段内为模型外推">插值段</span>';
  return out;
}
/* 结果是否落在没有中间锚点的宽段里 */
const isCoarse = (y, score) => y.coarseAbove > 0 && score != null && score > y.coarseAbove;

/* ---------------------------------------------------------------- 状态 */
// pct 是换算锚点：只有直接改分数/位次时才更新，切换年份时保持不变，
// 这样 2007→2025→2007 能原样回到出发点，不被取整误差一路带偏。
const state = { src:DATA.defaultYear, score:DATA.defaultScore, pct:0, mat:"rank" };

const clampScore = (v, year) => {
  const y = BY.get(year || state.src);
  return Math.min(y.top, Math.max(y.base, Math.round(v) || y.base));
};
function commitScore(v){
  state.score = clampScore(v);
  const y = BY.get(state.src);
  state.pct = rankOf(y, state.score).rank / y.total;
}
function commitRank(r){
  const y = BY.get(state.src);
  const R = Math.min(y.total, Math.max(1, Math.round(r) || 1));
  state.score = scoreAt(y, R).score;
  state.pct = R / y.total;
}
function readHash(){
  const m = /^#?(\d{4})[-/](\d{2,3})$/.exec(location.hash);
  if (!m || !BY.has(+m[1])) return;
  state.src = +m[1];
  commitScore(+m[2]);
}
function writeHash(){
  const h = "#" + state.src + "-" + state.score;
  if (location.hash !== h) history.replaceState(null, "", h);
}

/* ------------------------------------------------------------ 顶部指标 */
(function masthead(){
  const totals = YEARS.map(y => y.total);
  $("mYears").textContent = YEARS.length;
  $("mSpan").textContent  = YEARS[0].year + "–" + YEARS[YEARS.length-1].year;
  $("mMin").textContent   = wan(Math.min.apply(null, totals));
  $("mMax").textContent   = wan(Math.max.apply(null, totals));
})();

/* ---------------------------------------------------------- 年份选择器 */
(function yearPicker(){
  const box = $("segYear");
  YEARS.forEach((y, i) => {
    if (i && y.year >= NEW_ERA && YEARS[i-1].year < NEW_ERA){
      const gap = document.createElement("span");
      gap.className = "gap"; gap.setAttribute("aria-hidden", "true");
      box.appendChild(gap);
    }
    const b = document.createElement("button");
    b.type = "button"; b.dataset.v = y.year; b.textContent = y.year;
    b.addEventListener("click", () => setYear(y.year));
    box.appendChild(b);
  });
})();

function setYear(year){
  const next = BY.get(year);
  // 换年份时保持百分位不变，比保持分数不变更有意义
  state.src = year;
  state.score = scoreAt(next, Math.max(1, Math.round(state.pct * next.total))).score;
  render();
}

/* ------------------------------------------------------------ 分数输入 */
const scoreIn = $("scoreIn"), rankIn = $("rankIn"), scoreRange = $("scoreRange");
const setScore = v => { commitScore(v); render(); };
scoreIn.addEventListener("input", e => {
  const y = BY.get(state.src), v = parseInt(e.target.value, 10);
  if (!isNaN(v) && v >= y.base && v <= y.top){ commitScore(v); render("score"); }
});
scoreIn.addEventListener("blur",    e => setScore(parseInt(e.target.value, 10)));
scoreIn.addEventListener("keydown", e => { if (e.key === "Enter") e.target.blur(); });
rankIn.addEventListener("input", e => {
  const y = BY.get(state.src), v = parseInt(e.target.value, 10);
  if (!isNaN(v) && v >= 1 && v <= y.total){ commitRank(v); render("rank"); }
});
rankIn.addEventListener("blur",    e => { commitRank(parseInt(e.target.value, 10)); render(); });
rankIn.addEventListener("keydown", e => { if (e.key === "Enter") e.target.blur(); });
scoreRange.addEventListener("input", e => setScore(+e.target.value));
$("incBtn").addEventListener("click", () => setScore(state.score + 1));
$("decBtn").addEventListener("click", () => setScore(state.score - 1));

$("segMat").addEventListener("click", e => {
  const b = e.target.closest("button[data-v]");
  if (!b) return;
  state.mat = b.dataset.v;
  $("segMat").querySelectorAll("button").forEach(x =>
    x.setAttribute("aria-pressed", String(x.dataset.v === state.mat)));
  drawMatrix();
});

/* ------------------------------------------------------------ KPI 区块 */
function drawKpis(){
  const y = BY.get(state.src), s = state.score;
  const r = rankOf(y, s);
  const band = s < y.top ? cumAt(y, s) - cumAt(y, s + 1) : topCum(y);
  const p = r.rank / y.total;
  const cells = [
    { lab:"全省位次", val:prefix(r.bound) + fmt(r.rank), sub:y.year + " 年 " + y.track, accent:true },
    { lab:"累计百分位", val:pctText(p), sub:"位次 ÷ 当年考生数" },
    { lab:"同分人数", val:fmt(band), sub:s < y.top ? s + " 分整" : s + " 分及以上" },
    { lab:"当年考生数", val:fmt(y.total),
      sub:"150 分及以上" + (y.estimated ? "（估计）" : "") }
  ];
  $("kpis").innerHTML = cells.map(c =>
    '<div class="kpi' + (c.accent ? " accent" : "") + '">' +
      '<div class="k-lab">' + c.lab + '</div>' +
      '<div class="k-val">' + c.val + '</div>' +
      '<div class="k-sub">' + c.sub + '</div></div>').join("");
}

/* ------------------------------------------------------------ 结果表格 */
let rows = [];     // 供小图复用
function drawTable(){
  const src = BY.get(state.src), s = state.score;
  rows = YEARS.map(y => Object.assign({ y:y }, convert(src, s, y)));
  const maxAbs = Math.max(1, ...rows.map(r => Math.abs(r.score - s)));

  $("resBody").innerHTML = rows.map((r, i) => {
    const d = r.score - s, self = r.y.year === src.year;
    const w = Math.abs(d) / maxAbs * 50;      // 半宽百分比
    const bar = d === 0 ? "" :
      '<b style="' + (d > 0 ? "left:50%;background:var(--up);" : "right:50%;background:var(--down);") +
      "width:" + w.toFixed(2) + '%"></b>';
    const era = i && r.y.year >= NEW_ERA && rows[i-1].y.year < NEW_ERA;
    return '<tr class="' + (self ? "self " : "") + (era ? "eragap" : "") + '">' +
      '<td><span class="y-cell">' + r.y.year + tags(r.y, r.score) + '</span></td>' +
      '<td class="num eq">' + prefix(r.bound) + r.score + '</td>' +
      '<td class="num"><span class="dwrap"><span class="dnum ' +
        (d > 0 ? "pos" : d < 0 ? "neg" : "zero") + '">' + signed(d) + '</span>' +
        '<span class="dbar"><i></i>' + bar + '</span></span></td>' +
      '<td class="num">' + (r.bound === "above" ? "≤" : r.bound === "under" ? ">" : "") + fmt(r.real) + '</td>' +
      '<td class="num">' + pctText(r.real / r.y.total) + '</td>' +
      '<td class="num">' + fmt(r.y.total) + (r.y.estimated ? ' <span class="cap">est</span>' : "") + '</td></tr>';
  }).join("");

  const capped = rows.filter(r => r.bound).map(r => r.y.year);
  $("resNote").innerHTML =
    "分差 = 该年等位分 − " + src.year + " 年的 " + s + " 分。正值（橙）说明那一年的分数整体偏高，" +
    "同样的位次要考出更高的分；负值（蓝）反之。位次与百分位是<strong>等位分在该年的实际落点</strong>，" +
    "因分数只能取整，通常比目标百分位（" + pctText(rows[0].pct) + "）略靠后。" +
    (capped.length ? "　<strong>" + capped.join("、") + "</strong> 年该位次超出了一分一段表逐分公布的范围，只能给出边界值。" : "") +
    (rows.some(r => isCoarse(r.y, r.score))
      ? "　标「插值段」的年份，该分数落在重建时没有中间锚点的宽段内，只能当作趋势看。" : "");
}

/* ---------------------------------------------------------------- 小图 */
const NS = "http://www.w3.org/2000/svg";
const SPARK = { w:190, h:52, pad:3 };

function el(name, attrs){
  const n = document.createElementNS(NS, name);
  for (const k in attrs) n.setAttribute(k, attrs[k]);
  return n;
}

function drawSmall(){
  const src = BY.get(state.src), s = state.score;
  // 横轴：基准年逐分公布的范围，低于 250 分的样本没人关心，也易受各年下限影响
  const x0 = Math.max(src.base, 250), x1 = src.top;

  // 先把十三条曲线全算出来，取共同纵轴 —— 小图不共用刻度就没有意义
  const curves = YEARS.map(y => {
    const pts = [];
    for (let sc = x0; sc <= x1; sc++){
      const c = convert(src, sc, y);
      if (c.bound){ if (pts.length) break; else continue; }
      pts.push([sc, c.score - sc]);
    }
    return { y:y, pts:pts };
  });
  const all = curves.reduce((a,c) => a.concat(c.pts.map(p => p[1])), [0]);
  const lim = Math.max(1, Math.max.apply(null, all.map(Math.abs)));
  const lo = -lim, hi = lim;

  const iw = SPARK.w - SPARK.pad*2, ih = SPARK.h - SPARK.pad*2;
  const X = v => SPARK.pad + (v - x0) / (x1 - x0 || 1) * iw;
  const Y = v => SPARK.pad + (hi - v) / (hi - lo) * ih;

  $("smGrid").innerHTML = "";
  curves.forEach(c => {
    const r = rows.find(x => x.y.year === c.y.year);
    const d = r.score - s, self = c.y.year === src.year;

    const card = document.createElement("article");
    card.className = "sm" + (self ? " self" : "");
    card.innerHTML =
      '<div class="sm-top"><span class="sm-yr">' + c.y.year + "</span>" + tags(c.y, r.score) + "</div>" +
      '<div class="sm-val"><span class="sm-eq">' +
        (r.bound ? '<span class="cap">' + prefix(r.bound) + "</span>" : "") + r.score + "</span>" +
        '<span class="sm-d ' + (d > 0 ? "pos" : d < 0 ? "neg" : "zero") + '">' + signed(d) + "</span></div>";

    const svg = el("svg", { viewBox:"0 0 " + SPARK.w + " " + SPARK.h,
                            preserveAspectRatio:"none", role:"img",
                            "aria-label":c.y.year + " 年的分差曲线" });
    svg.appendChild(el("rect", { class:"spark-frame", x:.5, y:.5,
                                 width:SPARK.w-1, height:SPARK.h-1, rx:3 }));
    svg.appendChild(el("line", { class:"spark-zero", x1:SPARK.pad, x2:SPARK.w-SPARK.pad,
                                 y1:Y(0), y2:Y(0) }));
    if (c.pts.length > 1){
      // 零线上下分色：同一条折线按正负切成两段绘制
      const hue = g => g > 0 ? "var(--up)" : g < 0 ? "var(--down)" : "var(--flat)";
      let run = [], sign = Math.sign(c.pts[0][1]);
      const flush = () => {
        if (run.length > 1)
          svg.appendChild(el("path", {
            class:"spark-line",
            d:run.map((p,i) => (i ? "L" : "M") + X(p[0]).toFixed(1) + " " + Y(p[1]).toFixed(1)).join(" "),
            stroke:hue(sign) }));
      };
      c.pts.forEach(p => {
        const sg = Math.sign(p[1]);
        if (sg !== sign){ run.push(p); flush(); run = [p]; sign = sg; }
        else run.push(p);
      });
      flush();
    }
    if (s >= x0 && s <= x1)
      svg.appendChild(el("line", { class:"spark-mark", x1:X(s), x2:X(s),
                                   y1:SPARK.pad, y2:SPARK.h-SPARK.pad }));
    card.appendChild(svg);

    const foot = document.createElement("div");
    foot.className = "sm-foot";
    foot.textContent = (r.bound === "above" ? "≤" : r.bound === "under" ? ">" : "第 ") +
      fmt(r.real) + (r.bound ? " 名" : " 名") + " · " + wan(c.y.total) + " 万人";
    card.appendChild(foot);
    $("smGrid").appendChild(card);
  });

  padGrid();
  $("smSrc").textContent = src.year;
  $("smNote").innerHTML = "小图横轴为 " + x0 + "–" + x1 + " 分，纵轴统一为 ±" +
    Math.round(lim) + " 分。曲线在触及该年一分一段表的公布边界处收笔。";
}

/* auto-fill 的列数随宽度变化，用空格子补满最后一行 */
function padGrid(){
  const grid = $("smGrid");
  grid.querySelectorAll(".sm.filler").forEach(n => n.remove());
  const cols = getComputedStyle(grid).gridTemplateColumns.split(" ").filter(Boolean).length;
  const short = cols ? (cols - YEARS.length % cols) % cols : 0;
  for (let i = 0; i < short; i++){
    const f = document.createElement("div");
    f.className = "sm filler"; f.setAttribute("aria-hidden", "true");
    grid.appendChild(f);
  }
}
window.addEventListener("resize", () => { clearTimeout(window.__pg); window.__pg = setTimeout(padGrid, 150); });

/* ---------------------------------------------------------------- 对照表 */
const RANK_ROWS = [10,50,100,300,500,1000,2000,3000,5000,10000,20000,30000,50000,80000];
const PCT_ROWS  = [0.0001,0.0005,0.001,0.003,0.005,0.01,0.02,0.05,0.1,0.2,0.3,0.5];

function drawMatrix(){
  const byRank = state.mat === "rank";
  const list = byRank ? RANK_ROWS : PCT_ROWS;
  const src = BY.get(state.src);
  const myRank = rankOf(src, state.score).rank;
  const cur = byRank ? myRank : myRank / src.total;

  let hiIdx = -1, best = Infinity;
  list.forEach((v,i) => {
    const d = Math.abs(Math.log(v) - Math.log(cur));
    if (d < best){ best = d; hiIdx = i; }
  });

  const eraAt = i => i && YEARS[i].year >= NEW_ERA && YEARS[i-1].year < NEW_ERA;
  const head = "<colgroup><col>" + YEARS.map(y =>
      "<col" + (y.year === src.year ? ' class="hi"' : "") + ">").join("") + "</colgroup>" +
    "<thead><tr><th>" + (byRank ? "位次" : "百分位") + "</th>" +
    YEARS.map((y,i) => '<th class="num' + (eraAt(i) ? " era" : "") + '">' + y.year + "</th>").join("") +
    "</tr></thead>";

  const body = "<tbody>" + list.map((v,i) => {
    const label = byRank ? "前 " + fmt(v) + " 名" : "前 " + pctText(v);
    const cells = YEARS.map((y,j) => {
      const R = byRank ? Math.min(y.total, v) : Math.max(1, Math.round(v * y.total));
      const r = scoreAt(y, R);
      const mark = r.bound === "above" ? '<span class="cap">+</span>'
                 : r.bound === "under" ? '<span class="cap">−</span>' : "";
      return '<td class="num' + (eraAt(j) ? " era" : "") + '">' + r.score + mark + "</td>";
    }).join("");
    return '<tr class="' + (i === hiIdx ? "hi" : "") + '"><th scope="row">' + label + "</th>" + cells + "</tr>";
  }).join("") + "</tbody>";

  const foot = "<tfoot><tr><th>考生数</th>" +
    YEARS.map((y,i) => '<td class="num' + (eraAt(i) ? " era" : "") + '">' + wan(y.total) + " 万</td>").join("") +
    "</tr></tfoot>";

  $("matTable").innerHTML = head + body + foot;
}

/* ------------------------------------------------------------ 绥化对照 */
const SH = DATA.suihua || [];
const AX = { w:212, h:30, r0:1, r1:1000 };   // 位次用对数轴，左端最好

/* 位次 -> 归一化横坐标（0 最好） */
const axX = r => Math.log10(Math.max(1, Math.min(AX.r1, r))) / Math.log10(AX.r1);

/* 该分数在该年是否落在没有中间锚点的宽段里 —— 落进去位次就不可信 */
function shRank(y, score){
  if (score == null || !y) return null;
  if (isCoarse(y, score)) return { bad:true };
  const r = rankOf(y, score);
  return { rank:r.rank, bound:r.bound, pct:r.rank / y.total };
}

function scoreCell(y, score, info){
  if (score == null) return '<td><div class="sc none"><b>—</b><small>无记录</small></div></td>';
  if (!info || info.bad)
    return '<td><div class="sc"><b>' + score + '</b><small>位次不可用</small></div></td>';
  return '<td><div class="sc"><b>' + score + "</b><small>第 " + fmt(info.rank) +
         " 名 · 前 " + pctText(info.pct) + "</small></div></td>";
}

function drawSuihua(){
  if (!SH.length){ $("sec-suihua").hidden = true; return; }
  const base = BY.get(state.src);
  const span = SH[0].year + "–" + SH[SH.length-1].year;
  $("shTitle").textContent = "绥化市高考（" + span + "）";

  const head = "<thead><tr>" +
    "<th>年份</th>" +
    '<th class="num">清华录取线</th>' +
    '<th class="num">绥化市最高分</th>' +
    '<th class="num">绥化一中最高分</th>' +
    '<th class="axhead">全省位次<svg viewBox="0 0 ' + AX.w + ' 16" aria-hidden="true">' +
      [1,10,100,1000].map(r =>
        '<text class="ax-tick" x="' + (axX(r)*AX.w).toFixed(1) + '" y="12" text-anchor="' +
        (r === 1 ? "start" : r === AX.r1 ? "end" : "middle") + '">' + fmt(r) + "</text>").join("") +
      "</svg></th>" +
    '<th class="num">折合 ' + base.year + " 年</th>" +
    "</tr></thead>";

  let anyBad = false, anyMissing = false;
  const body = "<tbody>" + SH.map(rec => {
    const y = BY.get(rec.year);
    if (!y) return "";
    const q  = shRank(y, rec.qinghua);
    const c  = shRank(y, rec.city);
    const sc = shRank(y, rec.school);
    if ((q && q.bad) || (c && c.bad) || (sc && sc.bad)) anyBad = true;
    if (rec.city == null || rec.school == null) anyMissing = true;

    // 位次点图：上行为市最高分，下行为一中最高分，竖线为清华线
    let strip = '<svg class="dot" viewBox="0 0 ' + AX.w + " " + AX.h + '" role="img" aria-label="' +
      rec.year + ' 年绥化各分数的全省位次">';
    if (q && !q.bad)
      strip += '<rect class="dot-pass" x="0" y="2" width="' + (axX(q.rank)*AX.w).toFixed(1) +
               '" height="' + (AX.h-4) + '" rx="2"/>';
    strip += '<line class="dot-base" x1="0" y1="' + (AX.h/2) + '" x2="' + AX.w + '" y2="' + (AX.h/2) + '"/>';
    if (q && !q.bad)
      strip += '<line class="dot-qh" x1="' + (axX(q.rank)*AX.w).toFixed(1) + '" y1="2" x2="' +
               (axX(q.rank)*AX.w).toFixed(1) + '" y2="' + (AX.h-2) + '"/>';
    if (c && !c.bad)
      strip += '<circle class="dot-city" cx="' + (axX(c.rank)*AX.w).toFixed(1) + '" cy="9" r="4.5"/>';
    if (sc && !sc.bad)
      strip += '<circle class="dot-school" cx="' + (axX(sc.rank)*AX.w).toFixed(1) + '" cy="21" r="4.5"/>';
    if (!q || q.bad)
      strip += '<text class="dot-na" x="2" y="' + (AX.h/2+3.5) + '">位次不可用</text>';
    strip += "</svg>";

    // 折合到当前基准年：以绥化市最高分为准，缺则用一中最高分并标注
    let foldTxt = '<div class="sc none"><b>—</b><small>无记录</small></div>';
    const pick = rec.city != null ? { s:rec.city, tag:"市最高分" }
               : rec.school != null ? { s:rec.school, tag:"一中最高分" } : null;
    if (pick){
      const info = shRank(y, pick.s);
      if (!info || info.bad)
        foldTxt = '<div class="sc"><b>—</b><small>位次不可用</small></div>';
      else if (rec.year === base.year)
        foldTxt = '<div class="sc"><b>' + pick.s + '</b><small>即基准年本身</small></div>';
      else {
        const cv = convert(y, pick.s, base);
        foldTxt = '<div class="sc"><b>' + prefix(cv.bound) + cv.score +
                  "</b><small>" + pick.tag + "</small></div>";
      }
    }

    return "<tr><td>" + rec.year + tags(y, rec.city != null ? rec.city : rec.school) + "</td>" +
      scoreCell(y, rec.qinghua, q) + scoreCell(y, rec.city, c) + scoreCell(y, rec.school, sc) +
      '<td class="strip">' + strip + "</td>" +
      "<td>" + foldTxt + "</td></tr>";
  }).join("") + "</tbody>";

  $("shTable").innerHTML = head + body;

  const bits = ["横轴是全省位次的对数刻度，越靠左越靠前；带底色的一段表示达到了当年清华录取线。" +
                "最后一列把绥化市最高分按同一累计百分位折算到 " + base.year + " 年，可与页面上方的换算结果直接对读。"];
  if (anyMissing) bits.push("空缺处是该年没有留下分数记录，不是零分。");
  if (anyBad) bits.push("<strong>2004 年的位次一律留空</strong>：该年官方表在 600 分以上只有一段（600–693 分，1,935 人）" +
    "且无中间锚点，重建时这 1,935 人被模型几乎全压在 600–620 分，620 分以上的位次是模型假象，不能用。");
  $("shNote").innerHTML = bits.join("　");
}

